-- Larkspur Health (fictional): data platform RFI: stage "exported".
DO $demo$
DECLARE
  owner uuid := (SELECT id FROM auth.users WHERE email = 'james.okafor@example.invalid');
  opp   uuid;
  sess  uuid;
  qid   uuid;
  kind  text;
BEGIN
  IF owner IS NULL OR EXISTS (SELECT 1 FROM public.opportunities WHERE name = 'Larkspur Health (fictional): data platform RFI') THEN RETURN; END IF;
  PERFORM set_config('request.jwt.claims', json_build_object('sub', owner, 'role', 'authenticated')::text, true);
  INSERT INTO public.opportunities (name, due_date, created_by, owner_id)
  VALUES ('Larkspur Health (fictional): data platform RFI', current_date + 14, owner, owner) RETURNING id INTO opp;
  INSERT INTO public.rfi_sessions (file_name, question_count, opportunity_id)
  VALUES ('larkspur-data-platform-rfi.docx', 8, opp) RETURNING id INTO sess;
  INSERT INTO public.rfi_questions (session_id, position, question, customer_ref, generated_answer, confidence, retrieval_score, sources_json, answerability, verdict, gate, gate_reason, language, embedding_model, judge_model, judge_best_ref, judge_reason, draft_model, prompt_version, calibration_set, draft_kind, cited_refs, processing_note, processed_at) VALUES
    (sess, 0, 'How does your organisation encrypt data in transit between services?', '3.1', 'We protect all data in transit using TLS 1.2 or higher, with TLS 1.3 preferred for new integrations. We explicitly disable weak cipher suites and manage certificates through a documented lifecycle process that includes automated renewal alerts. Communication between internal services is encrypted using mutual TLS (mTLS) within our zero-trust architecture.

[References: KB-0002]', 1, 0.6930541301318176, '[{"id":"KB-0002","score":0.6930541301318176}]'::jsonb, 2.6930541301318174, 'yes', NULL, NULL, 'en', 'voyage-4', 'claude-haiku-5-5', 'KB-0002', 'KB-0002 directly states that data in transit is protected by TLS 1.2+ and that internal service-to-service traffic uses mutual TLS, answering the question about encryption between services.', 'claude-haiku-5-5', 'draft-2026-10-23.1', '2026-10-22.3 (all 363 questions; checked by 5-fold cross-validation)', 'generated', ARRAY['KB-0002']::text[], NULL, '2026-10-25T10:50:41.866Z'::timestamptz),
    (sess, 1, 'In which regions is customer data stored?', '3.2', 'Insufficient evidence: the matched knowledge-base entries do not answer this question (The entries describe data residency controls, including per-customer residency requirements enforced through cloud region configuration and automated controls against unauthorized geographies, but they do not name the regions or countries where customer data is stored). It needs an answer written by a person.', 0.853, 0.5687427656317937, '[{"id":"KB-0070","score":0.5687427656317937}]'::jsonb, 1.5687427656317938, 'partly', NULL, NULL, 'en', 'voyage-4', 'claude-haiku-5-5', 'KB-0070', 'The entry describes data residency controls and enforcement in general terms but does not name the storage regions, which is the specific fact the question asks for.', 'claude-haiku-5-5', 'draft-2026-10-23.1', '2026-10-22.3 (all 363 questions; checked by 5-fold cross-validation)', 'insufficient_evidence', ARRAY[]::text[], NULL, '2026-10-25T10:50:43.616Z'::timestamptz),
    (sess, 2, 'What controls protect databases that hold personal data?', '3.3', 'We protect databases with role-based access following least-privilege principles, and we enforce encrypted connections for all client connections. Database activity is monitored through audit logging integrated with our SIEM. Privileged database accounts are managed via PAM with session recording. Sensitive data fields, including PII and financial information, are masked or tokenized where feasible. Database configurations are audited against CIS benchmarks quarterly.

[References: KB-0045]', 0.96, 0.6186763710186036, '[{"id":"KB-0045","score":0.6186763710186036}]'::jsonb, 2.6186763710186036, 'yes', NULL, NULL, 'en', 'voyage-4', 'claude-haiku-5-5', 'KB-0045', 'KB-0045 directly describes database controls for sensitive data, including least-privilege access, encrypted connections, audit logging, PAM for privileged accounts, and masking or tokenization of PII.', 'claude-haiku-5-5', 'draft-2026-10-23.1', '2026-10-22.3 (all 363 questions; checked by 5-fold cross-validation)', 'generated', ARRAY['KB-0045']::text[], NULL, '2026-10-25T10:50:41.282Z'::timestamptz),
    (sess, 3, 'How do you comply with GDPR?', '3.4', 'We comply with GDPR through a compliance program overseen by a designated Data Protection Officer (DPO). The program covers data mapping, privacy impact assessments (DPIAs), and a documented legal basis for each processing activity. Data subject rights requests (access, erasure, portability) are handled through a defined workflow with a 30-day response SLA. Annual privacy audits validate compliance, and staff receive mandatory GDPR training upon hire and annually thereafter.

[References: KB-0015]', 0.96, 0.6236683753539237, '[{"id":"KB-0015","score":0.6236683753539237}]'::jsonb, 2.623668375353924, 'yes', NULL, NULL, 'en', 'voyage-4', 'claude-haiku-5-5', 'KB-0015', 'KB-0015 directly describes how the organization complies with GDPR, covering a DPO, DPIAs, legal bases, data subject rights workflow, audits, and training.', 'claude-haiku-5-5', 'draft-2026-10-23.1', '2026-10-22.3 (all 363 questions; checked by 5-fold cross-validation)', 'generated', ARRAY['KB-0015']::text[], NULL, '2026-10-25T10:50:45.512Z'::timestamptz),
    (sess, 4, 'How is sensitive data handled in test and development environments?', '3.5', 'Production data is prohibited from use in our development, test, and staging environments by policy. Where realistic test data is required, we use a data anonymization and synthetic data generation process to create functionally equivalent data sets that contain no real PII or sensitive information. Access to non-production environments is controlled separately from production and reviewed quarterly.

[References: KB-0081]', 0.96, 0.6254138352669715, '[{"id":"KB-0081","score":0.6254138352669715}]'::jsonb, 2.6254138352669716, 'yes', NULL, NULL, 'en', 'voyage-4', 'claude-haiku-5-5', 'KB-0081', 'KB-0081 states production data is prohibited in dev, test, and staging, with anonymized or synthetic data used instead, directly answering how sensitive data is handled in test and development environments.', 'claude-haiku-5-5', 'draft-2026-10-23.1', '2026-10-22.3 (all 363 questions; checked by 5-fold cross-validation)', 'generated', ARRAY['KB-0081']::text[], NULL, '2026-10-25T10:50:45.086Z'::timestamptz),
    (sess, 5, 'How do you secure data used by machine learning systems?', '3.6', 'AI/ML systems that process sensitive data are subject to the same data governance and security controls as our other systems. We apply data minimization to training datasets and anonymize or pseudonymize PII before it is used in model training. Before deployment, we assess model outputs for privacy risks, including re-identification potential. Access to AI/ML platforms and training data is controlled through role-based access control (RBAC), and we maintain audit logs of data access.

[References: KB-0085]', 1, 0.6883856374785732, '[{"id":"KB-0085","score":0.6883856374785732}]'::jsonb, 2.6883856374785733, 'yes', NULL, NULL, 'en', 'voyage-4', 'claude-haiku-5-5', 'KB-0085', 'KB-0085 directly answers how data for AI/ML systems is secured, covering minimization, PII anonymization, output privacy assessment, RBAC access control, and audit logging.', 'claude-haiku-5-5', 'draft-2026-10-23.1', '2026-10-22.3 (all 363 questions; checked by 5-fold cross-validation)', 'generated', ARRAY['KB-0085']::text[], NULL, '2026-10-25T10:50:48.035Z'::timestamptz),
    (sess, 6, 'What are your fees for implementation services?', '3.7', 'Pricing question: a person answers this. No draft is written, and pricing answers are never added to the knowledge base automatically.', 0, 0.16874246859635247, '[{"id":"KB-0025","score":0.16874246859635247},{"id":"KB-0024","score":0.16207862120710997},{"id":"KB-0049","score":0.16122404407474067}]'::jsonb, 0.16874246859635247, 'no', 'pricing', 'Rules matched: fee. Classifier: The question asks about fees for implementation services, which is a request for pricing information.', 'en', 'voyage-4', 'claude-haiku-5-5', 'KB-0024', 'The entries cover zero trust, identity provisioning, and privacy-by-design, but none mention fees, pricing, or costs for implementation services, so the question is unanswered.', NULL, NULL, '2026-10-22.3 (all 363 questions; checked by 5-fold cross-validation)', 'person_required', ARRAY[]::text[], NULL, '2026-10-25T10:50:46.274Z'::timestamptz),
    (sess, 7, 'Describe your incident response process.', '3.8', 'We follow the NIST SP 800-61 framework for incident response, with defined phases: preparation, detection, containment, eradication, recovery, and post-incident review. A dedicated Security Incident Response Team (SIRT) is on call 24/7. We categorize incidents by severity, with associated SLA targets for response and notification. We conduct post-incident reviews within 5 business days and track findings to closure.

[References: KB-0006]', 1, 0.6427630469643656, '[{"id":"KB-0006","score":0.6427630469643656}]'::jsonb, 2.6427630469643657, 'yes', NULL, NULL, 'en', 'voyage-4', 'claude-haiku-5-5', 'KB-0006', 'KB-0006 describes the incident response framework, phases, on-call response team, severity-based SLAs, and post-incident review process, directly answering the question about the incident response process.', 'claude-haiku-5-5', 'draft-2026-10-23.1', '2026-10-22.3 (all 363 questions; checked by 5-fold cross-validation)', 'generated', ARRAY['KB-0006']::text[], NULL, '2026-10-25T10:50:49.181Z'::timestamptz);
