  UPDATE public.rfi_questions SET final_answer = 'We follow the UK GDPR and the EU GDPR. Our Data Protection Officer reviews new processing activities, and we keep records of processing and data protection impact assessments for high-risk processing.' WHERE id = (SELECT id FROM public.rfi_questions WHERE session_id = sess AND customer_ref = '3.4');
  UPDATE public.rfi_questions SET status = 'accepted' WHERE id = (SELECT id FROM public.rfi_questions WHERE session_id = sess AND customer_ref = '3.4');
  UPDATE public.rfi_questions SET final_answer = 'Our platform holds customer data in UK and EU regions only, chosen by the customer at onboarding. No customer data is stored outside the chosen region.' WHERE id = (SELECT id FROM public.rfi_questions WHERE session_id = sess AND customer_ref = '3.2');
  UPDATE public.rfi_questions SET status = 'accepted' WHERE id = (SELECT id FROM public.rfi_questions WHERE session_id = sess AND customer_ref = '3.2');
  PERFORM public.bulk_accept(sess, 0.8);
  -- Everything else decided individually: drafts accepted as written, the rest marked not answered.
  FOR qid, kind IN SELECT q.id, q.draft_kind FROM public.rfi_questions q WHERE q.session_id = sess AND q.status = 'pending' ORDER BY q.position LOOP
    UPDATE public.rfi_questions SET status = CASE WHEN kind IN ('generated', 'assembled') THEN 'accepted' ELSE 'skipped' END WHERE id = qid;
  END LOOP;
  PERFORM public.record_export(sess);
  PERFORM set_config('request.jwt.claims', '', true);
END $demo$;

-- Harbour Logistics (fictional): RFQ security schedule: stage "archived".
DO $demo$
DECLARE
  owner uuid := (SELECT id FROM auth.users WHERE email = 'maya.patel@example.invalid');
  opp   uuid;
  sess  uuid;
  qid   uuid;
  kind  text;
BEGIN
  IF owner IS NULL OR EXISTS (SELECT 1 FROM public.opportunities WHERE name = 'Harbour Logistics (fictional): RFQ security schedule') THEN RETURN; END IF;
  PERFORM set_config('request.jwt.claims', json_build_object('sub', owner, 'role', 'authenticated')::text, true);
  INSERT INTO public.opportunities (name, due_date, created_by, owner_id)
  VALUES ('Harbour Logistics (fictional): RFQ security schedule', current_date + -10, owner, owner) RETURNING id INTO opp;
  INSERT INTO public.rfi_sessions (file_name, question_count, opportunity_id)
  VALUES ('harbour-rfq-security-schedule.xlsx', 6, opp) RETURNING id INTO sess;
  INSERT INTO public.rfi_questions (session_id, position, question, customer_ref, generated_answer, confidence, retrieval_score, sources_json, answerability, verdict, gate, gate_reason, language, embedding_model, judge_model, judge_best_ref, judge_reason, draft_model, prompt_version, calibration_set, draft_kind, cited_refs, processing_note, processed_at) VALUES
    (sess, 0, 'What SOC 2 reports do you hold?', 'S1', 'We hold a SOC 2 Type II report covering the Trust Services Criteria for Security, Availability, and Confidentiality, issued by an independent AICPA-accredited auditor. The audit period covers a minimum of six months, and the report is refreshed annually. Bridge letters are available on request for periods between reports. Copies of the report are available under NDA to qualified prospective and current customers.

[References: KB-0017]', 0.911, 0.5488312761657221, '[{"id":"KB-0017","score":0.5488312761657221}]'::jsonb, 2.548831276165722, 'yes', NULL, NULL, 'en', 'voyage-4', 'claude-haiku-5-5', 'KB-0017', 'KB-0017 directly states the company holds a SOC 2 Type II report covering Security, Availability, and Confidentiality, which answers what SOC 2 reports are held.', 'claude-haiku-5-5', 'draft-2026-10-23.1', '2026-10-22.3 (all 363 questions; checked by 5-fold cross-validation)', 'generated', ARRAY['KB-0017']::text[], NULL, '2026-10-25T10:50:53.038Z'::timestamptz),
    (sess, 1, 'How do you manage privileged accounts?', 'S2', 'We manage privileged accounts through a Privileged Access Management (PAM) solution. Privileged accounts are inventoried, and access is just-in-time, with session recording and password vaulting with automated rotation. We eliminate standing privileged access wherever possible, using time-limited, approval-gated elevation instead. Privileged account activity is subject to enhanced monitoring and anomaly alerting within our SIEM.

[References: KB-0031]', 0.96, 0.6159884170053993, '[{"id":"KB-0031","score":0.6159884170053993}]'::jsonb, 2.6159884170053993, 'yes', NULL, NULL, 'en', 'voyage-4', 'claude-haiku-5-5', 'KB-0031', 'KB-0031 directly describes how privileged accounts are managed: PAM solution, just-in-time access, session recording, password vaulting with rotation, and monitoring, which answers the question fully.', 'claude-haiku-5-5', 'draft-2026-10-23.1', '2026-10-22.3 (all 363 questions; checked by 5-fold cross-validation)', 'generated', ARRAY['KB-0031']::text[], NULL, '2026-10-25T10:50:53.172Z'::timestamptz),
    (sess, 2, 'Describe your approach to single sign-on and identity federation.', 'S3', 'We implement Single Sign-On (SSO) using SAML 2.0 and OIDC protocols, federated through a central enterprise identity provider. All business applications are onboarded to SSO to centralize access control. We enforce multi-factor authentication (MFA) at the identity provider level for all federated authentications. We review federated identity trust relationships annually and revoke orphaned or unused application integrations.

[References: KB-0075]', 1, 0.6603944248826867, '[{"id":"KB-0075","score":0.6603944248826867}]'::jsonb, 2.6603944248826865, 'yes', NULL, NULL, 'en', 'voyage-4', 'claude-haiku-5-5', 'KB-0075', 'KB-0075 directly describes SSO via SAML 2.0 and OIDC through a central identity provider, plus federation trust review and MFA enforcement, which answers the question''s request for the approach.', 'claude-haiku-5-5', 'draft-2026-10-23.1', '2026-10-22.3 (all 363 questions; checked by 5-fold cross-validation)', 'generated', ARRAY['KB-0075']::text[], NULL, '2026-10-25T10:50:53.273Z'::timestamptz),
    (sess, 3, 'How are your build and release pipelines secured?', 'S4', 'We harden our software build pipeline with access controls that limit modification rights to authorized CI/CD service accounts. All build artifacts are signed using code signing certificates traceable to an internal certificate authority, and artifact integrity is verified at each deployment stage. Pipeline configurations are version-controlled, and changes require security team review. Third-party build tool dependencies are managed through a curated internal package mirror that is subject to vulnerability scanning.

[References: KB-0099]', 1, 0.7128342050730675, '[{"id":"KB-0099","score":0.7128342050730675}]'::jsonb, 2.7128342050730674, 'yes', NULL, NULL, 'en', 'voyage-4', 'claude-haiku-5-5', 'KB-0099', 'KB-0099 directly describes how build and release pipelines are secured: restricted CI/CD access, signed artifacts, integrity checks at each deployment stage, version-controlled configs with security review, and vetted dependencies.', 'claude-haiku-5-5', 'draft-2026-10-23.1', '2026-10-22.3 (all 363 questions; checked by 5-fold cross-validation)', 'generated', ARRAY['KB-0099']::text[], NULL, '2026-10-25T10:51:03.695Z'::timestamptz),
    (sess, 4, 'How do you secure email against phishing and spoofing?', 'S5', 'We secure email against phishing and spoofing through a secure email gateway that provides anti-phishing, anti-malware, and spam filtering. We use DMARC, DKIM, and SPF records to prevent domain spoofing. Advanced threat protection scans attachments and URLs in sandboxed environments, and suspicious emails are quarantined for review. Our security awareness training includes phishing simulation exercises.

[References: KB-0035]', 1, 0.6696145686287308, '[{"id":"KB-0035","score":0.6696145686287308}]'::jsonb, 2.669614568628731, 'yes', NULL, NULL, 'en', 'voyage-4', 'claude-haiku-5-5', 'KB-0035', 'KB-0035 directly describes anti-phishing filtering, DMARC/DKIM/SPF records to prevent domain spoofing, and attachment and URL scanning, which together answer how email is secured against phishing and spoofing.', 'claude-haiku-5-5', 'draft-2026-10-23.1', '2026-10-22.3 (all 363 questions; checked by 5-fold cross-validation)', 'generated', ARRAY['KB-0035']::text[], NULL, '2026-10-25T10:50:56.422Z'::timestamptz),
    (sess, 5, 'How do you manage security for staff working remotely?', 'S6', 'We apply the same security policies to remote workers as to on-site employees, enforced through MDM, endpoint protection, and ZTNA-based access controls. Security awareness training includes modules on home office risks, such as unsecured Wi-Fi and physical eavesdropping. VPN use is mandatory when accessing sensitive systems, and remote worker equipment is company-issued and managed.

[References: KB-0043]', 1, 0.6854222469969923, '[{"id":"KB-0043","score":0.6854222469969923}]'::jsonb, 2.685422246996992, 'yes', NULL, NULL, 'en', 'voyage-4', 'claude-haiku-5-5', 'KB-0043', 'KB-0043 directly describes how remote workers are secured: same policies as on-site staff, MDM, endpoint protection, ZTNA, mandatory VPN, company-issued managed equipment, and home-office training.', 'claude-haiku-5-5', 'draft-2026-10-23.1', '2026-10-22.3 (all 363 questions; checked by 5-fold cross-validation)', 'generated', ARRAY['KB-0043']::text[], NULL, '2026-10-25T10:50:57.051Z'::timestamptz);
